$ErrorActionPreference='Stop'
$folder=Join-Path $env:USERPROFILE 'Documents/Codex/cross-device-dev/handoffs/wake-worker-education-delivery-20261112'
if(-not (Test-Path -LiteralPath $folder -PathType Container)){throw 'Expected existing handoff folder is missing'}
$path=Join-Path $folder 'WINDOWS_WAKE_AUTHORITY_UPDATE_20261112.md'
$bytes=[Convert]::FromBase64String('')
[IO.File]::WriteAllBytes($path,$bytes)
$actual=(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()
if($actual -ne '8e6a73cc34c3906d6046fef0c3ada183bc08f8856bd7e858db43878280af1778'){throw 'Windows readback hash mismatch'}
@{path=$path;sha256=$actual;bytes=$bytes.Length;containsCommit=(Get-Content -Raw -LiteralPath $path).Contains('ba883b7283ae2d70b77c0dc3e292b85e59320b47')}|ConvertTo-Json -Compress
